	} {
		if got := FormatMajor(c.amount, c.cur); got != c.want {
			t.Errorf("FormatMajor(%d, %s) = %q, want %q", c.amount, c.cur, got, c.want)
		}
	}
}

func TestParseFormatRoundTrip(t *testing.T) {
	for _, c := range []struct {
		major string
		cur   Currency
	}{{"12.50", USD}, {"1000", JPY}, {"1.250", KWD}, {"0.99", EUR}} {
		n, err := ParseMajor(c.major, c.cur)
